(x, y, t) => {
  const w1 = Math.sin(x*0.012 + Math.sin(y*0.018 + t*0.3)*2 + t*0.2) * 22;
  const w2 = Math.cos(y*0.015 + Math.cos(x*0.013 - t*0.25)*2 - t*0.15) * 20;
  const w3 = Math.sin((x+y)*0.008 + t*0.4) * Math.cos((x-y)*0.01 - t*0.3) * 16;
  const sx = x + w1 + w3*0.5, sy = y + w2 + w3*0.5;
  const wells = [
    [160+Math.sin(t*0.3)*120, 80+Math.cos(t*0.25)*60, 1.0],
    [320+Math.cos(t*0.35)*100, 160+Math.sin(t*0.4)*70, 0.8],
    [240+Math.sin(t*0.2+2)*140, 120+Math.cos(t*0.3+1)*90, 1.2],
    [100+Math.cos(t*0.45+1)*80, 200+Math.sin(t*0.5+3)*50, 0.6],
    [380+Math.sin(t*0.28+4)*70, 50+Math.cos(t*0.55+2)*50, 0.9]
  ];
  let potential = 0, kinetic = 0;
  for (const [wX, wY, mass] of wells) {
    const dx = sx-wX, dy = sy-wY, dist = Math.sqrt(dx*dx+dy*dy)+1;
    potential -= mass*30/dist;
    kinetic += mass*8/Math.sqrt(dist)*Math.sin(dist*0.08-t*1.5+Math.atan2(dy,dx)*2);
  }
  potential /= wells.length; kinetic /= wells.length;
  const totalE = potential + kinetic;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.1,2.5],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.12,2.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.08,3.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.14,1.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.09,2.8],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.11,2.2],
    [200+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.6)*40,0.07,3.2],
    [400+Math.cos(t*0.45)*50,200+Math.sin(t*0.8)*50,0.13,1.6]
  ];
  let act = 0, inh = 0;
  for (const [sX, sY, freq, spd] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act += Math.sin(d*freq-t*spd);
    inh += Math.cos(d*freq*0.6+t*spd*0.7+1.2);
  }
  act /= src.length; inh /= src.length;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.04-ang*3-t*1.2)*0.5+Math.sin(dist*0.06+ang*5-t*0.8)*0.3)*(1+potential*0.02);
  const turb = (Math.sin(sx*0.03+sy*0.02+t*0.9)+Math.sin(sx*0.025-sy*0.035+t*1.3))/2;
  const reaction = Math.tanh((act-inh*0.65+spiral*0.4+totalE*0.15+turb*0.2)*3.8);
  const cell = Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t*0.7)*0.6;
  const membrane = Math.tanh(cell*2.5)*0.2;
  const blend = reaction*0.8+membrane*0.2, v = blend*0.5+0.5;
  const pal = [[2,2,8],[5,10,42],[0,45,90],[0,170,210],[90,0,210],[255,0,150],[255,110,210],[255,255,255]];
  const idx = v*(pal.length-1), i = Math.min(idx|0,pal.length-2), f = idx-i;
  const glow = Math.pow(Math.abs(reaction),0.6);
  const edge = Math.abs(reaction)>0.55?1.35+glow*0.45:0.75+glow*0.3;
  const bloom = Math.pow(glow,3)*0.6;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*edge+bloom*120)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*edge+bloom*50)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*edge+bloom*200)|0)
  ];
}
